//! Generate or check the committed TypeScript bindings for the native database
//! contracts.
//!
//! Default: write `src/lib/native/contracts.generated.ts`.
//! `--check`: compare the generated bytes to the committed file without
//! rewriting; exit nonzero on mismatch.

use std::path::PathBuf;
use std::process::ExitCode;

fn output_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("src-tauri always has a parent repo root")
        .join("src/lib/native/contracts.generated.ts")
}

fn main() -> ExitCode {
    let check = std::env::args().any(|arg| arg == "--check");
    let generated = notchy_lib::database::generate_bindings();
    let path = output_path();

    if check {
        match std::fs::read_to_string(&path) {
            Ok(committed) if committed == generated => {
                println!("bindings are current: {}", path.display());
                ExitCode::SUCCESS
            }
            Ok(_) => {
                eprintln!("bindings are out of date: {}", path.display());
                eprintln!("run `pnpm generate:db-contracts` and commit the result");
                ExitCode::FAILURE
            }
            Err(error) => {
                eprintln!(
                    "failed to read committed bindings {}: {error}",
                    path.display()
                );
                ExitCode::FAILURE
            }
        }
    } else {
        let dir = path.parent().expect("output path has a parent");
        if let Err(error) = std::fs::create_dir_all(dir) {
            eprintln!("failed to create {}: {error}", dir.display());
            return ExitCode::FAILURE;
        }
        match std::fs::write(&path, generated) {
            Ok(()) => {
                println!("wrote {}", path.display());
                ExitCode::SUCCESS
            }
            Err(error) => {
                eprintln!("failed to write {}: {error}", path.display());
                ExitCode::FAILURE
            }
        }
    }
}
